sys_script_include.script:
var TrainingUtils = Class.create();
TrainingUtils.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {
    checkDuplicateSchedule: function() {
        //gs.info("ryuki: entrou na funcao");
        var training = this.getParameter('sysparm_training');
        var startDate = this.getParameter('sysparm_start_date');
        //gs.info("ryuki curso: " + training);
        //gs.info("ryuki data: "+ startDate);
        var grSchedule = new GlideRecord("x_1092529_traini_0_training_schedule");
        grSchedule.addEncodedQuery("training=" + training + "^training_dateON" + startDate + "@javascript:gs.dateGenerate('" + startDate + "','start')@javascript:gs.dateGenerate('" + startDate + "','end')");
        grSchedule.setLimit(1);
        grSchedule.query();

        if (grSchedule.next()) {
            // gs.info("ryuki: entrou no if");
            // gs.info("ryuki: data do gliderecord: "+ grSchedule.training_date);
            return true;
        } else {
            // gs.info("ryuki: entrou no else");
            return false;
        }

    },

    getGroupMembers: function(groupID) {
        var membersArray = [];
        var grGroupMember = new GlideRecord("sys_user_grmember");
        grGroupMember.addQuery("group", groupID);
        grGroupMember.query();
        while (grGroupMember.next()) {
            membersArray.push(grGroupMember.getValue('user'));
        }
        return membersArray.toString();
    },

    checkScheduleEntry: function() {
        var schedule = this.getParameter('sysparm_training_schedule');
        var userId = this.getParameter('sysparm_userid');

        var grScheduleEntry = new GlideRecord("x_1092529_traini_0_inscription");
        grScheduleEntry.addEncodedQuery("training_schedule=" + schedule + "^user=" + userId);
        grScheduleEntry.query();

        if (grScheduleEntry.next()) {
            var results = {
				"registered": "true",
                "state": grScheduleEntry.getDisplayValue("state")
            };
            return JSON.stringify(results);
        } else {
            return null;
        }
    },

    type: 'TrainingUtils'
});
